{
  "question": "Prove that the function f(x) = x^3 - 3x + 1 is continuous at x = 2.",
  "approach": {
    "definition_of_continuity": "A function f(x) is continuous at a point c if three conditions are met: 1) f(c) is defined, 2) lim_(x->c) f(x) exists, and 3) lim_(x->c) f(x) = f(c).",
    "step_1": {
      "description": "Verify that f(2) is defined and calculate the value.",
      "calculation": "Substitute x = 2 into the function: f(2) = (2)^3 - 3(2) + 1 = 8 - 6 + 1 = 3."
    },
    "step_2": {
      "description": "Evaluate the limit as x approaches 2.",
      "calculation": "Since polynomial functions are continuous everywhere, direct substitution can be used. lim_(x->2) (x^3 - 3x + 1) = 2^3 - 3(2) + 1 = 3."
    },
    "step_3": {
      "description": "Compare the function value and the limit.",
      "result": "Since f(2) = 3 and lim_(x->2) f(x) = 3, the condition is satisfied."
    },
    "conclusion": "The function f(x) meets all conditions for continuity at x = 2."
  }
}

